head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16400";
scwin.edu_rnd = null;
scwin.edu_rnd1 = null;
scwin.edu_rnd2 = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.edu_rnd = $c.util.getComponent('edu_rnd');
        scwin.edu_rnd1 = $c.util.getComponent('edu_rnd1');
        scwin.edu_rnd2 = $c.util.getComponent('edu_rnd2');
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_fillGen();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16400.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_disclsEduApctTpCd", fn: function(){ return ((dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '11' || (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '41' || (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '81'); } }, { id: "if_disclsEduApctTpCd_2", fn: function(){ return ((dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '12' || (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '42' || (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '81'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_43", entity: "dlt_educationList", countIds: [], cells: [{ childId: "option_45", fn: function (v, i) { return String(v("disclsEduApplSeq")) + "," + String(v("disclsEduAcptStrtDd")) + "," + String(v("disclsEduAcptEndDd")) + "," + String(v("disclsEduEvtItmExpYn")) + "," + String(v("partcPersInputYn")); } }, { childId: "__rc0", fn: function (v, i) { return String(v("disclsEduCrsNm")); } }] },
        { genId: "c_foreach_49", entity: "dlt_educationList", countIds: [], cells: [{ childId: "option_51", fn: function (v, i) { return String(v("disclsEduApplSeq")) + "," + String(v("disclsEduAcptStrtDd")) + "," + String(v("disclsEduAcptEndDd")) + "," + String(v("disclsEduEvtItmExpYn")) + "," + String(v("partcPersInputYn")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("disclsEduCrsNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Submit();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_sltGubun_onchange
 * @description slc_sltGubun 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_sltGubun_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.change(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16400.slc_sltGubun_onchange' }); }
};

/**
 * @method
 * @name slc_sltEduRnd1_onchange
 * @description slc_sltEduRnd1 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_sltEduRnd1_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.getDsclEduRct(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16400.slc_sltEduRnd1_onchange' }); }
};

/**
 * @method
 * @name slc_sltEduRnd2_onchange
 * @description slc_sltEduRnd2 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_sltEduRnd2_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.getDsclEduRct(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16400.slc_sltEduRnd2_onchange' }); }
};

/**
 * @method
 * @name btn_Reset_onclick
 * @description 「초기화」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Reset_onclick = function(e){
    try {
        scwin.reset()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16400.btn_Reset_onclick' }); }
};

/**
 * @method
 * @name btn_Submit_onclick
 * @description 「신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Submit_onclick = async function(e){
    try {
        await scwin.submit()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16400.btn_Submit_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Submit
 * @description Submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Submit = async function () {
    const sbmOptions = {
        id: "tx_fn_Submit",
        method: "post",
        action: "/support/eduRspn.do",
        ref: "dma_SubmitReq",
        target: "dlt_educationList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name onlyNum
 * @description only Num 처리
 * @param {*} event event
 * @returns {void}
 * @hidden N
 */
scwin.onlyNum = function (event) {

    const charCode = (event.charCode || event.charCode === 0) ? event.charCode : (($c.util.getKeyCode(event)) ? event.keyCode : $c.util.getKeyCode(event));
    if (charCode === 8 || charCode === 16 || charCode === 47 || charCode === 109 || charCode === 189) {
        event.returnValue = true;
    }
    if ((charCode >= 48) && (charCode <= 57)) {
        event.returnValue = true;
    } else {
        event.returnValue = false;
    }
};

/**
 * @method
 * @name change
 * @description change 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.change = function (code) {
    const form = (document.eduForm || { elements: [] });
    $c.util.getComponent('slc_roomTpCd').setValue("");
    $c.util.getComponent('ipt_eduPartcCnt').setValue("");
    const divRoomYn = $c.util.getComponent("roomAttendYn");
    const divCntYn = $c.util.getComponent("eduPartcYn");
    if (code.value === '1') {
        scwin.edu_rnd.setStyle("display", 'none');
        scwin.edu_rnd1.setStyle("display", 'block');
        scwin.edu_rnd2.setStyle("display", 'none');
        $c.util.getComponent("slc_sltEduRnd2").setValue("");
        $c.util.getComponent('txt_dsclEduRct').setLabel("");
    } else {
        if (code.value === '2') {
            scwin.edu_rnd.setStyle("display", 'none');
            scwin.edu_rnd1.setStyle("display", 'none');
            scwin.edu_rnd2.setStyle("display", 'block');
            $c.util.getComponent("slc_sltEduRnd1").setValue("");
            $c.util.getComponent('txt_dsclEduRct').setLabel("");
        } else {
            scwin.edu_rnd.setStyle("display", 'block');
            scwin.edu_rnd1.setStyle("display", 'none');
            scwin.edu_rnd2.setStyle("display", 'none');
            $c.util.getComponent("slc_sltEduRnd1").setValue("");
            $c.util.getComponent("slc_sltEduRnd2").setValue("");
            $c.util.getComponent('txt_dsclEduRct').setLabel("");
        }
    }
    (!divRoomYn ? console.warn('[sdd] 표시 전환 대상 미해결: divRoomYn') : (('none') === 'none' ? (divRoomYn.hide ? divRoomYn.hide() : void 0) : (divRoomYn.show ? divRoomYn.show() : void 0)));
    (!divCntYn ? console.warn('[sdd] 표시 전환 대상 미해결: divCntYn') : (('none') === 'none' ? (divCntYn.hide ? divCntYn.hide() : void 0) : (divCntYn.show ? divCntYn.show() : void 0)));
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function () {
    const form = (document.eduForm || { elements: [] });
    const dsclEduGubun = $c.util.getComponent('slc_sltGubun').getValue();
    let arr;
    const today = $c.util.getComponent('dma_SubmitReq').get('today');
    let sdate = '';
    let edate = '';
    let disableYn = '';
    let title = '';
    const divRoomYn = $c.util.getComponent("roomAttendYn");
    const divCntYn = $c.util.getComponent("eduPartcYn");
    if (dsclEduGubun === '1') {
        arr = slc_sltEduRnd1.value.split(",");
        title = $c.util.getComponent('slc_sltEduRnd1').getItemText($c.util.getComponent('slc_sltEduRnd1').getSelectedIndex());
    } else {
        if (dsclEduGubun === '2') {
            arr = slc_sltEduRnd2.value.split(",");
            title = $c.util.getComponent('slc_sltEduRnd2').getItemText($c.util.getComponent('slc_sltEduRnd2').getSelectedIndex());
        } else {
            arr = slt_edu_rnd.value.split(",");
            title = $c.util.getComponent('slc_sltEduRnd').getItemText($c.util.getComponent('slc_sltEduRnd').getSelectedIndex());
        }
    }
    if (title === '2011년 상장법인 공시담당자 사이버교육') {
        await $c.win.alert("신청인원이 많아 9월15일부로 교육신청을 마감하겠습니다. 2012년에도 강의를 개설할 예정이니 많은 이용바랍니다");
        return;
    }
    if (arr !== "") {
        $c.util.getComponent('dma_SubmitReq').set('disclsEduApplSeq', arr[0]);
        sdate = arr[1];
        edate = arr[2];
        disableYn = arr[3];
        if (today > edate) {
            await $c.win.alert("제출 기간이 지났습니다.");
            return;
        }
        if (today < sdate) {
            await $c.win.alert("아직 제출 기간이 아닙니다.");
            return;
        }
        if (divRoomYn.style.display === 'block' && ($c.util.getComponent('slc_roomTpCd').getValue() === null ? '' : String($c.util.getComponent('slc_roomTpCd').getValue())) === '') {
            await $c.win.alert("간담회 참석여부는 필수 입니다.");
            return;
        }
        let attCnt = $c.util.getComponent('ipt_eduPartcCnt').getValue(); if (attCnt === null) { attCnt = ''; }
        if (divCntYn.style.display === 'block' && (attCnt === '' || attCnt === '0')) {
            await $c.win.alert("교육참가 예상인원은 1명 이상 입니다.");
            return false;
        }
        if (today >= sdate && today <= edate) {
            if (dsclEduGubun === '1') {
                form.action = 'eduRspn.do';
                $c.util.getComponent('dma_SubmitReq').set('method', 'registerResponsibilityEducationSmpl');
                $c.util.getComponent('dma_SubmitReq').set('disableYn', disableYn);
                await scwin.tx_fn_Submit();
            } else {
                form.action = 'eduChrg.do';
                $c.util.getComponent('dma_SubmitReq').set('method', 'educationChargeFormSmpl');
                $c.util.getComponent('dma_SubmitReq').set('disableYn', disableYn);
                await scwin.tx_fn_Submit();
            }
        }
    } else {
        if (dsclEduGubun === "") {
            await $c.win.alert("교육 구분을 선택해 주세요.");
            return;
        } else {
            await $c.win.alert("교육 회차를 선택해 주세요");
            return;
        }
    }
};

/**
 * @method
 * @name reset
 * @description reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.reset = function () {
    const form = (document.eduForm || { elements: [] });
    $c.util.getComponent('dma_SubmitReq').reset();
    const t_dsclEduRct = $c.util.getComponent("txt_dsclEduRct");
    scwin.edu_rnd.setStyle("display", 'block');
    scwin.edu_rnd1.setStyle("display", 'none');
    scwin.edu_rnd2.setStyle("display", 'none');
    t_dsclEduRct.innerHTML = "";
};

/**
 * @method
 * @name getDsclEduRct
 * @description get Dscl Edu Rct 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getDsclEduRct = function (obj) {
    const slt_edu_rnd = obj.value;
    const t_dsclEduRct = $c.util.getComponent("txt_dsclEduRct");
    const arr = slt_edu_rnd.split(",");
    let sdate;
    let edate;
    if (arr !== "") {
        sdate = arr[1];
        edate = arr[2];
        t_dsclEduRct.innerHTML = "<b>신청 기간 : " + sdate + " ~ " + edate + "</b>";
    } else {
        t_dsclEduRct.innerHTML = "";
    }
    if (arr.length === 5) {
        const divRoomYn = $c.util.getComponent("roomAttendYn");
        const divCntYn = $c.util.getComponent("eduPartcYn");
        const tmpRoomYn = arr[3];
        const tmpEduCntYn = arr[4];
        if (tmpRoomYn === 'Y') {
            (!divRoomYn ? console.warn('[sdd] 표시 전환 대상 미해결: divRoomYn') : (('block') === 'none' ? (divRoomYn.hide ? divRoomYn.hide() : void 0) : (divRoomYn.show ? divRoomYn.show() : void 0)));
        } else {
            (!divRoomYn ? console.warn('[sdd] 표시 전환 대상 미해결: divRoomYn') : (('none') === 'none' ? (divRoomYn.hide ? divRoomYn.hide() : void 0) : (divRoomYn.show ? divRoomYn.show() : void 0)));
        }
        if (tmpEduCntYn === 'Y') {
            (!divCntYn ? console.warn('[sdd] 표시 전환 대상 미해결: divCntYn') : (('block') === 'none' ? (divCntYn.hide ? divCntYn.hide() : void 0) : (divCntYn.show ? divCntYn.show() : void 0)));
        } else {
            (!divCntYn ? console.warn('[sdd] 표시 전환 대상 미해결: divCntYn') : (('none') === 'none' ? (divCntYn.hide ? divCntYn.hide() : void 0) : (divCntYn.show ? divCntYn.show() : void 0)));
        }
    }
};
